:      'this shell script can be used to check your current news':      'installation, but be warned: it is sloowwwwwwww.....':      '$Id: check.sh_v 1.1 90/08/31 13:57:59 ud Exp $':      'Copyright (C) 1990 Ulrich Dessauer, Germering, Germany'::      'Insert here your local configuration':BATCHDIR=/h0/SPOOL/BATCHNEWSDIR=/h0/SPOOL/NEWSSPOOLDIR=/h0/SPOOL/RNEWSNEWSLIB=/h0/USR/LIB/NEWSHISTORY=${NEWSLIB}/HISTORYNEWS=news::      'Get GID.UID from password file'OWNER=`grep ${NEWS}, /dd/SYS/password | gawk -F, '{ print  $3 }'`if [ X$OWNER = X ]then  OWNER=2.39fiecho 'Pass one, check existance of files.'for file in $BATCHDIR $NEWSDIR $SPOOLDIR $NEWSLIB $HISTORYdo  echo Check $file  if test ! -d $file  then    echo -r $file 'is not available, Create it ? [y] '    read ans    case X$ans in      X | X[Yy]*)        makdir $file        chown -u=$NEWS $file       ;;      X[Qq]*)        echo 'Script aborted.'       exit 1    esac  else    own=`dir -ne $file | grep -v Bytecount | grep -ve=-------- | gawk '{ print $1 }'`    if [ X$own != X$OWNER ]    then      echo -r 'Owner of' $file 'is not news, change it? [y] '      read ans      case X$ans in       X | X[Yy]*)          chown -u=$NEWS $file          ;;        X[Qq]*)          echo 'Script aborted.'         exit 1      esac    else      echo 'Everything looks okay for' $file    fi  fidonefor xfile in Active Distributions Sys send_uunamedo  file=${NEWSLIB}/${xfile}  echo Check $file  if test ! -f $file  then    echo -r $file 'is not available, Create it ? [y] '    read ans    case X$ans in      X | X[Yy]*)        touch $file        chown -u=$NEWS $file        ;;      X[Qq]*)        echo 'Script aborted.'        exit 1    esac  else    own=`dir -e $file | grep -v Bytecount | grep -ve=-------- | gawk '{ print $1 }'`    if [ X$own != X$OWNER ]    then      echo -r 'Owner of' $file 'is not news, change it? [y] '      read ans      case X$ans in       X | X[Yy]*)          chown -u=$NEWS $file          ;;        X[Qq]*)          echo 'Script aborted.'          exit 1      esac    else      echo 'Everything looks okay for' $file    fi  fidoneecho 'Pass two, slightly syntax check of files in' $NEWSLIBcd $NEWSLIBecho 'Check Sys file'cnt=`wc -l Sys | gawk '{ print $1 }'`i=1while test $i -le $cntdo  sed -n ${i}p Sys | read line  case X$line in    X#*)      echo 'Skip comment line'      ;;    *)      count=`echo $line | gawk -F: '{ print NF }'`      system=`echo $line | gawk -F: '{ print $1 }' | gawk -F/ '{ print $1 }'`      case $count in        3)         echo $system 'will be spooled into' $SPOOLDIR          ;;        4)         cmd=`echo $line | gawk -F: '{ print $4 }'`         echo $system 'will use the command' $cmd         ;;        *)         echo 'This line may contain some errors (has' $count 'entries)'          echo $line         ;;      esac      ;;  esac  i=`expr $i + 1`doneecho 'Check Active file'cnt=`wc -l Active | gawk '{ print $1 }'`i=1while test $i -le $cntdo  sed -n ${i}p Active | read line  case X$line in    X#*)      echo 'Skip comment line'      ;;    *)      count=`echo $line | gawk -F: '{ print NF }'`      case $count in        2)         echo $line | gawk -F: '{ print $2 }' | read start end mod moderator         status=OKAY          if test $start -gt $end         then           echo 'Start (' $start ') is greater than end (' $end ') in line'           echo $line           status=ERR         fi         if [ X$mod = Xy ]         then           if [ X$moderator = X ]           then             echo 'No moderator in moderated group, you should add one; in line'             echo $line             status=ERR           fi         fi         if [ $status = OKAY ]         then           echo $line 'looks okay'         fi          ;;        *)         echo 'This line may contain some errors (has' $count 'entries)'          echo $line         ;;      esac      ;;  esac  i=`expr $i + 1`done